from collections import deque, Counter
def neighbors(I):
    H,W=len(I),len(I[0])
    for i in range(H):
        for j in range(W):
            if I[i][j]==0: continue
            nb=sum(1 for a,b in [(i-1,j),(i+1,j),(i,j-1),(i,j+1)] if 0<=a<H and 0<=b<W and I[a][b]==I[i][j])
            yield (i,j,I[i][j],nb)
